UPDATE employees
SET name = #{name}, email = #{email},
    department1 = #{department1}, department2 = #{department2}, department3 = #{department3},
    rank = #{rank}
WHERE employee_id = #{employeeId}

UPDATE assets
SET current_user_id = #{employeeId}, status = '사용중'
WHERE asset_id = #{assetId}

UPDATE assets
SET current_user_id = NULL, status = '재고'
WHERE asset_id = #{assetId}

UPDATE asset_history 
SET employee_id = NULL, prev_user_id = NULL 
WHERE employee_id = #{id} OR prev_user_id = #{id}
